/**
 * Tiny i18n helper for user-facing strings generated by the backend
 * (in-app notifications and SMS bodies).
 *
 * Cameroon is a French-primary market, so 'fr' is the default locale.
 * 'en' is available via `msg(key, 'en', vars)` and is used automatically
 * when a user record carries a `locale`/`preferredLanguage` field set to
 * an English value (see `userLocale`).
 *
 * NOTE: API error `message` fields are intentionally NOT localized — the
 * mobile app localizes errors by the stable `error` code. Only generated
 * notification/SMS text goes through this helper.
 */

export type Locale = 'fr' | 'en';

const DEFAULT_LOCALE: Locale = 'fr';

export type MessageVars = Record<string, string | number>;

