/**
 * Return the localized message for `key`, interpolating `{var}` placeholders
 * with values from `vars`. Unknown keys fall back to the key itself so a
 * missing translation never crashes a notification path.
 */
export function msg(key: string, locale: Locale = DEFAULT_LOCALE, vars: MessageVars = {}): string {
  const entry = MESSAGES[key];
  const template = entry?.[locale] ?? entry?.[DEFAULT_LOCALE] ?? key;
  return template.replace(/\{(\w+)\}/g, (_, name) =>
    vars[name] !== undefined ? String(vars[name]) : `{${name}}`
  );
}

/**
 * Resolve a user's preferred locale. The User model currently has no locale
 * column; this reads `preferredLanguage`/`locale` defensively so a future
 * schema addition is picked up automatically. Defaults to French.
 */
export function userLocale(user: object | null | undefined): Locale {
  const u = (user ?? {}) as { preferredLanguage?: unknown; locale?: unknown };
  const raw = (u.preferredLanguage ?? u.locale ?? '').toString().toLowerCase();
  return raw.startsWith('en') ? 'en' : DEFAULT_LOCALE;
}
